use crate::init::uniform;
use crate::rwkv_cmix::RwkvCmix;
use ndarray::{Array1,Array2};
#[derive(Clone,Debug)]pub struct MoeRouter{pub input_size:usize,pub num_experts:usize,pub top_k:usize,pub weight:Array2<f32>}
impl MoeRouter{pub fn new(i:usize,e:usize,k:usize,s:u64)->Self{assert!(i>0&&e>0&&k>0&&k<=e);let q=1.0/(i as f32).sqrt();Self{input_size:i,num_experts:e,top_k:k,weight:uniform(e,i,-q,q,s)}}pub fn from_weight(w:Array2<f32>,k:usize)->Self{assert!(w.nrows()>0&&w.ncols()>0&&k>0&&k<=w.nrows());Self{input_size:w.ncols(),num_experts:w.nrows(),top_k:k,weight:w}}pub fn route(&self,x:&Array2<f32>)->Array2<f32>{let z=x.dot(&self.weight.t());let mut g=Array2::zeros(z.raw_dim());for r in 0..z.nrows(){let mut o:Vec<usize>=(0..self.num_experts).collect();o.sort_unstable_by(|&a,&b|z[[r,b]].total_cmp(&z[[r,a]]));let s=&o[..self.top_k];let m=s.iter().map(|&i|z[[r,i]]).fold(f32::NEG_INFINITY,f32::max);let sum:f32=s.iter().map(|&i|(z[[r,i]]-m).exp()).sum();for&i in s{g[[r,i]]=(z[[r,i]]-m).exp()/sum}}g}pub fn parameter_count(&self)->usize{self.weight.len()}}
#[derive(Clone,Debug)]pub struct MoeCmix{pub experts:Vec<RwkvCmix>,pub router:MoeRouter}
impl MoeCmix{pub fn new(c:usize,l:usize,n:usize,e:usize,k:usize,s:u64)->Self{let experts=(0..e).map(|i|RwkvCmix::new_seeded(c,l,n,s^(i as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15))).collect();Self{experts,router:MoeRouter::new(c,e,k,s)}}pub fn with_qat_3bit(self,on:bool)->Self{self.with_qat_bits(if on{3}else{0})}pub fn with_qat_bits(mut self,b:u8)->Self{for e in&mut self.experts{*e=e.clone().with_qat_bits(b)}self}pub fn from_experts(e:Vec<RwkvCmix>,r:MoeRouter)->Result<Self,String>{if e.is_empty()||e.len()!=r.num_experts||e.iter().any(|x|x.channels!=r.input_size){return Err("invalid MoE expert/router configuration".into())}Ok(Self{experts:e,router:r})}pub fn forward(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>)->(Array2<f32>,Array1<f32>){let g=self.router.route(x);let mut out=Array2::zeros(x.raw_dim());for i in 0..self.experts.len(){let rows:Vec<usize>=(0..x.nrows()).filter(|&r|g[[r,i]]!=0.0).collect();if rows.is_empty(){continue}let y=self.experts[i].forward_rows(x,prev,&rows);for(a,&r)in rows.iter().enumerate(){for c in 0..x.ncols(){out[[r,c]]+=g[[r,i]]*y[[a,c]]}}}(out,x.row(x.nrows()-1).to_owned())}pub fn parameter_count(&self)->usize{self.router.parameter_count()+self.experts.iter().map(RwkvCmix::parameter_count).sum::<usize>()}}
#[cfg(test)]mod tests{use super::*;#[test]fn qat_width_reaches_experts(){for b in[2u8,3,4,8]{let m=MoeCmix::new(8,0,4,3,2,7).with_qat_bits(b);assert!(m.experts.iter().all(|e|e.qat_bits==b));}}}
